class Student {

    int id;
    String name;
    int marks;

    void eat() {
        System.out.println(name + " student is eating");
    }

    void sleep() {
        System.out.println(name + " student is sleeping");
    }

    void study() {
        System.out.println(name + " student is studying");
    }
}

class StudentApp {

    public static void main(String[] args) {

        Student s1 = new Student();
        Student s2 = new Student();

        s1.id = 1;
        s1.name = "Sahana";
        s1.marks = 55;

        s2.id = 2;
        s2.name = "Omkar";
        s2.marks = 99;

        System.out.println(s1.id + " " + s1.name + " " + s1.marks);
        s1.eat();
        s1.sleep();
        s1.study();

        System.out.println(s2.id + " " + s2.name + " " + s2.marks);
        s2.eat();
        s2.sleep();
        s2.study();
    }
}

class Fan {

    int numberOfWings;
    String color;
    int cost;
    String brand;

    void rotate() {
        System.out.println(
            color + " " + brand + " fan with "
            + numberOfWings + " wings is rotating"
        );
    }

    void giveAir() {
        System.out.println(
            color + " " + brand + " fan with "
            + numberOfWings + " wings is giving air"
        );
    }
}

class FanApp {

    public static void main(String[] args) {

        Fan f1 = new Fan();

        f1.numberOfWings = 4;
        f1.color = "Blue";
        f1.cost = 2500;
        f1.brand = "Usha";

        f1.rotate();
        f1.giveAir();
    }
}

class Car {

    String brand;
    String color;
    int price;

    void start() {
        System.out.println(brand + " car is starting");
    }

    void stop() {
        System.out.println(brand + " car is stopping");
    }

    void drive() {
        System.out.println(brand + " car is moving");
    }
}

class CarApp {

    public static void main(String[] args) {

        Car c1 = new Car();

        c1.brand = "Tata";
        c1.color = "Black";
        c1.price = 1200000;

        System.out.println(c1.brand + " " + c1.color + " " + c1.price);

        c1.start();
        c1.drive();
        c1.stop();
    }
}

class Mobile {

    String brand;
    String model;
    int price;

    void call() {
        System.out.println(brand + " " + model + " is making a call");
    }

    void message() {
        System.out.println(brand + " " + model + " is sending a message");
    }

    void charge() {
        System.out.println(brand + " " + model + " is charging");
    }
}

class MobileApp {

    public static void main(String[] args) {

        Mobile m1 = new Mobile();

        m1.brand = "Samsung";
        m1.model = "Galaxy";
        m1.price = 50000;

        System.out.println(m1.brand + " " + m1.model + " " + m1.price);

        m1.call();
        m1.message();
        m1.charge();
    }
}

